using System;using System.IO;using System.Linq;using System.Collections.Generic;using UnityEngine;using UnityEditor;using UnityEditor.SceneManagement;using UnityEngine.Rendering;
public static class FixTreeAlphaClipping {
 const string A="Assets/NewMap/FiveHangars/TreeCutoutMaterials";
 public static string Main(){if(EditorApplication.isPlaying)throw new Exception("Edit mode required");var root=GameObject.Find("New_Map").transform;Directory.CreateDirectory(A);AssetDatabase.Refresh();var shader=Shader.Find("FreeHangar/Tree Cutout Toon");if(!shader)throw new Exception("Cutout shader unavailable");EditorSceneManager.SaveScene(root.gameObject.scene,"Temp/TreeOptimization/Gameplay.before-tree-alpha-fix.unity",true);var renderers=root.GetComponentsInChildren<LODGroup>().Where(l=>l.name.Contains("Tree")||l.transform.IsChildOf(root.Find("12_Farmyards_and_boundaries/Low poly hill groves"))).SelectMany(l=>l.GetLODs()).SelectMany(l=>l.renderers).Distinct().ToArray();var copies=new Dictionary<Material,Material>();int slots=0;
 foreach(var renderer in renderers){var materials=renderer.sharedMaterials;for(int i=0;i<materials.Length;i++){var source=materials[i];if(!source||!source.HasProperty("_TextureSample"))continue;if(!copies.TryGetValue(source,out var cutout)){string path=A+"/"+source.name+" - Tree cutout.mat";cutout=AssetDatabase.LoadAssetAtPath<Material>(path);if(!cutout){cutout=new Material(source){name=source.name+" - Tree cutout"};cutout.shader=shader;AssetDatabase.CreateAsset(cutout,path);}cutout.SetFloat("_AlphaClipping",1);cutout.SetFloat("_AlphaCutoff",.5f);cutout.SetFloat("_Cull",(float)CullMode.Off);cutout.SetOverrideTag("RenderType","TransparentCutout");cutout.renderQueue=(int)RenderQueue.AlphaTest;cutout.enableInstancing=true;EditorUtility.SetDirty(cutout);copies.Add(source,cutout);}materials[i]=cutout;slots++;}renderer.sharedMaterials=materials;}
 AssetDatabase.SaveAssets();EditorSceneManager.SaveScene(root.gameObject.scene);string report="Tree-only alpha clipping applied to "+slots+" material slots across "+renderers.Length+" LOD renderers, using "+copies.Count+" shared cutout materials. Existing toon atlas/ramp colours preserved. Alpha test 0.5, double-sided foliage, clipping in colour/depth/shadow passes. Shared building/ground materials untouched. LOD order remains high-detail close, lower-detail far.";File.WriteAllText("output/TreeOptimization/alpha-fix.txt",report);return report;
 }
}
